// Access to the Bambu Studio system presets embedded in data/bambu-a1.json
// (generated by tools/build_data.py from the official BambuStudio profiles).

export class Profiles {
  constructor(data) {
    this.data = data;
    this.schema = data.schema;
    this.template = data.template;
    this.validKeys = new Set([...Object.keys(data.schema), ...Object.keys(data.template)]);
  }

  printerModels() {
    return Object.keys(this.data.printers);
  }

  nozzles(model) {
    return Object.keys(this.data.printers[model].nozzles);
  }

  info(model, nozzle) {
    return this.data.printers[model].nozzles[nozzle];
  }

  modelId(model) {
    return this.data.printers[model].model_id;
  }

  machine(name) {
    return this.data.machines[name];
  }

  process(name) {
    return expand(this.data.process_base, this.data.processes[name]);
  }

  filament(name) {
    return expand(this.data.filament_base, this.data.filaments[name]);
  }

  filamentKeys() {
    return Object.keys(this.data.filament_base);
  }

  bed(model, nozzle = '0.4') {
    const m = this.machine(this.info(model, nozzle).machine);
    return bedFromArea(m.printable_area, m.printable_height);
  }

  // Picks the process preset whose layer height is closest to the requested one,
  // preferring a matching quality keyword ("Standard", "Fine", ...).
  suggestProcess(model, nozzle, layerHeight, qualityHint = '') {
    const info = this.info(model, nozzle);
    if (!layerHeight) return info.default_process;
    const hint = (qualityHint || '').toLowerCase();
    let best = null;
    for (const name of info.processes) {
      const lh = parseFloat(this.process(name).layer_height);
      const quality = name.replace(/^[\d.]+mm\s+/, '').split(' @')[0].toLowerCase();
      const score = Math.abs(lh - layerHeight) * 1000 + (hint && hint.includes(quality) ? 0 : 1) + (name === info.default_process ? -0.5 : 0);
      if (!best || score < best.score) best = { name, score };
    }
    return best.name;
  }

  // Maps a source filament description to the best Bambu preset available for the printer.
  suggestFilament(model, nozzle, src) {
    const info = this.info(model, nozzle);
    const list = info.filaments;
    const byBase = new Map();
    for (const n of list) {
      const base = presetBase(n);
      if (!byBase.has(base)) byBase.set(base, n);
    }
    // 1) Same preset family (e.g. "Bambu PLA Matte @BBL X1C" -> "Bambu PLA Matte @BBL A1").
    const srcName = (src.name || '').replace(/\s*\(.*?\)\s*$/, '');
    const base = presetBase(srcName);
    if (base && byBase.has(base)) return { name: byBase.get(base), exact: true };
    // 2) Same vendor + type keywords.
    const type = normalizeType(src.type || guessTypeFromName(srcName));
    const text = `${srcName} ${src.vendor || ''}`.toLowerCase();
    const generic = genericFor(type, text);
    for (const g of generic) {
      if (byBase.has(g)) return { name: byBase.get(g), exact: false };
    }
    return { name: info.default_filament, exact: false, unsupported: type };
  }
}

export function expand(base, diff) {
  const out = { ...base };
  for (const [k, v] of Object.entries(diff || {})) {
    if (v === null) delete out[k];
    else out[k] = v;
  }
  return out;
}

export function presetBase(name) {
  return (name || '').split(' @')[0].trim();
}

export function bedFromArea(area, height) {
  const pts = (Array.isArray(area) ? area : String(area || '').split(','))
    .map((p) => String(p).split('x').map(Number))
    .filter((p) => p.length === 2 && p.every(Number.isFinite));
  if (!pts.length) return null;
  const xs = pts.map((p) => p[0]);
  const ys = pts.map((p) => p[1]);
  const minX = Math.min(...xs), maxX = Math.max(...xs), minY = Math.min(...ys), maxY = Math.max(...ys);
  return { minX, minY, maxX, maxY, w: maxX - minX, d: maxY - minY, h: parseFloat(height) || 0 };
}

const TYPE_ALIASES = [
  [/^(pla\+|pla plus|pla pro|pla-plus|pla\s*\+)$/, 'PLA'],
  [/^pet$/, 'PETG'],
  [/^(flex|tpe|tpu\d*a?|tpu-\w+)$/, 'TPU'],
  [/^(nylon|pa6|pa12|paht|pa-ht)$/, 'PA'],
  [/^(pa6-cf|pa12-cf|paht-cf|nylon-cf|pa-cf)$/, 'PA-CF'],
  [/^(pa6-gf|pa-gf|paht-gf)$/, 'PA-GF'],
  [/^(pc-abs|pc\/abs)$/, 'PC'],
  [/^(asa-cf)$/, 'ASA-CF'],
];

export function normalizeType(t) {
  let s = String(t || '').trim().toLowerCase();
  if (!s) return '';
  for (const [re, v] of TYPE_ALIASES) if (re.test(s)) return v;
  return s.toUpperCase();
}

function guessTypeFromName(name) {
  const m = String(name || '').toUpperCase().match(/\b(PLA-CF|PETG-CF|PA-CF|PET-CF|ABS-GF|PLA|PETG|PCTG|ABS|ASA|TPU|PVA|HIPS|PA|PC|PP|PE|BVOH|EVA|PHA)\b/);
  return m ? m[1] : 'PLA';
}

// Candidate preset base names, most specific first.
function genericFor(type, text) {
  const has = (re) => re.test(text);
  const c = [];
  switch (type) {
    case 'PLA':
      if (has(/\bbambu\b/)) {
        if (has(/matte/)) c.push('Bambu PLA Matte');
        if (has(/silk\+|silk plus/)) c.push('Bambu PLA Silk+');
        if (has(/silk/)) c.push('Bambu PLA Silk');
        if (has(/tough\+/)) c.push('Bambu PLA Tough+');
        if (has(/tough/)) c.push('Bambu PLA Tough');
        if (has(/translucent/)) c.push('Bambu PLA Translucent');
        if (has(/metal/)) c.push('Bambu PLA Metal');
        if (has(/marble/)) c.push('Bambu PLA Marble');
        if (has(/sparkle/)) c.push('Bambu PLA Sparkle');
        if (has(/galaxy/)) c.push('Bambu PLA Galaxy');
        if (has(/glow/)) c.push('Bambu PLA Glow');
        if (has(/wood/)) c.push('Bambu PLA Wood');
        if (has(/aero/)) c.push('Bambu PLA Aero');
        if (has(/lite/)) c.push('Bambu PLA Lite');
        if (has(/basic|bambu pla\b/)) c.push('Bambu PLA Basic');
      }
      if (has(/polyterra/)) c.push('PolyTerra PLA');
      if (has(/polylite/)) c.push('PolyLite PLA');
      if (has(/overture/)) c.push(has(/matte/) ? 'Overture Matte PLA' : 'Overture PLA');
      if (has(/esun/)) c.push('eSUN PLA+');
      if (has(/sunlu/)) {
        if (has(/silk/)) c.push('SUNLU Silk PLA+');
        if (has(/matte/)) c.push('SUNLU PLA Matte');
        if (has(/marble/)) c.push('SUNLU PLA Marble');
        if (has(/wood/)) c.push('SUNLU Wood PLA');
        c.push('SUNLU PLA+');
      }
      if (has(/silk/)) c.push('Generic PLA Silk');
      if (has(/high speed|\bhs\b|hyper|rapid|speed/)) c.push('Generic PLA High Speed');
      c.push('Generic PLA');
      break;
    case 'PLA-CF':
      c.push(has(/bambu/) ? 'Bambu PLA-CF' : 'Generic PLA-CF', 'Generic PLA-CF', 'Generic PLA');
      break;
    case 'PETG':
      if (has(/bambu/)) {
        if (has(/\bhf\b|high flow/)) c.push('Bambu PETG HF');
        if (has(/translucent/)) c.push('Bambu PETG Translucent');
        if (has(/matte/)) c.push('Bambu PETG Matte');
        c.push('Bambu PETG Basic');
      }
      if (has(/polylite/)) c.push('PolyLite PETG');
      if (has(/sunlu/)) c.push('SUNLU PETG');
      if (has(/\bhf\b|high flow|high speed|hyper|rapid/)) c.push('Generic PETG HF');
      c.push('Generic PETG');
      break;
    case 'PETG-CF':
    case 'PET-CF':
      c.push(has(/bambu/) ? (type === 'PET-CF' ? 'Bambu PET-CF' : 'Bambu PETG-CF') : 'Generic PETG-CF', 'Generic PETG-CF', 'Generic PETG');
      break;
    case 'PCTG':
      c.push('Generic PCTG', 'Generic PETG');
      break;
    case 'ABS':
      if (has(/bambu/)) c.push('Bambu ABS');
      if (has(/polylite/)) c.push('PolyLite ABS');
      c.push('Generic ABS');
      break;
    case 'ABS-GF':
      c.push('Bambu ABS-GF', 'Generic ABS');
      break;
    case 'ASA':
    case 'ASA-CF':
      if (has(/bambu/)) c.push(type === 'ASA-CF' ? 'Bambu ASA-CF' : has(/aero/) ? 'Bambu ASA-Aero' : 'Bambu ASA');
      if (has(/polylite/)) c.push('PolyLite ASA');
      c.push('Generic ASA', 'Generic ABS');
      break;
    case 'TPU':
      if (has(/bambu/)) {
        if (has(/90a/)) c.push('Bambu TPU 90A');
        if (has(/ams/)) c.push('Bambu TPU for AMS');
        c.push('Bambu TPU 95A');
      }
      if (has(/ams/)) c.push('Generic TPU for AMS');
      c.push('Generic TPU');
      break;
    case 'PA':
    case 'PA-CF':
    case 'PA-GF':
      if (has(/bambu/)) c.push(type === 'PA' ? 'Bambu PA6-CF' : type === 'PA-GF' ? 'Bambu PA6-GF' : 'Bambu PA-CF');
      c.push(type === 'PA' ? 'Generic PA' : 'Generic PA-CF', 'Generic PA');
      break;
    case 'PC':
      c.push(has(/bambu/) ? 'Bambu PC' : 'Generic PC', 'Generic PC');
      break;
    case 'PVA':
      c.push(has(/bambu/) ? 'Bambu PVA' : 'Generic PVA', 'Generic PVA');
      break;
    case 'HIPS':
    case 'BVOH':
    case 'EVA':
    case 'PHA':
    case 'PE':
    case 'PE-CF':
    case 'PP':
    case 'PP-CF':
    case 'PP-GF':
      c.push(`Generic ${type}`);
      break;
    default:
      if (/support/.test(text)) c.push(has(/abs/) ? 'Bambu Support for ABS' : 'Bambu Support For PLA');
      c.push(`Generic ${type}`);
  }
  return c;
}
